package ru.codex.obslancamera;
import android.app.*;import android.os.*;import android.content.*;import android.hardware.Camera;import android.view.*;import android.widget.*;import com.google.zxing.*;import com.google.zxing.common.HybridBinarizer;import com.google.zxing.qrcode.QRCodeReader;import java.util.concurrent.*;
/** Local QR decoding. No Google service, account, network request or gallery access. */
@SuppressWarnings("deprecation") public class ScanActivity extends Activity implements SurfaceHolder.Callback {
 private Camera camera;private boolean busy;private volatile boolean alive=true;private final ExecutorService decode=Executors.newSingleThreadExecutor();
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(16,30,16,20);TextView title=new TextView(this);title.setText(Language.text("Наведите камеру на QR подключения в OBS"));title.setTextSize(20);root.addView(title);SurfaceView view=new SurfaceView(this);root.addView(view,new LinearLayout.LayoutParams(-1,0,1));Button cancel=new Button(this);cancel.setText(Language.text("Отмена"));cancel.setOnClickListener(v->finish());root.addView(cancel);setContentView(root);view.getHolder().addCallback(this);}
 public void surfaceCreated(SurfaceHolder holder){try{camera=Camera.open();Camera.Parameters p=camera.getParameters();for(Camera.Size s:p.getSupportedPreviewSizes())if(s.width==640&&s.height==480){p.setPreviewSize(s.width,s.height);break;}if(p.getSupportedFocusModes().contains(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE))p.setFocusMode(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE);camera.setParameters(p);camera.setDisplayOrientation(90);camera.setPreviewDisplay(holder);camera.setPreviewCallback((bytes,cam)->{if(busy||!alive)return;busy=true;Camera.Size size=cam.getParameters().getPreviewSize();byte[] copy=bytes.clone();decode.execute(()->{try{PlanarYUVLuminanceSource source=new PlanarYUVLuminanceSource(copy,size.width,size.height,0,0,size.width,size.height,false);Result result=new QRCodeReader().decode(new BinaryBitmap(new HybridBinarizer(source)));if((result.getText().startsWith("obslan://")||result.getText().startsWith("multicamera://"))&&alive)runOnUiThread(()->{setResult(RESULT_OK,new Intent().putExtra("pair",result.getText()));finish();});}catch(Exception ignored){}finally{busy=false;}});});camera.startPreview();}catch(Exception e){Toast.makeText(this,Language.text("Не удалось открыть сканер. Можно ввести адрес и ключ вручную."),Toast.LENGTH_LONG).show();finish();}}
 public void surfaceChanged(SurfaceHolder holder,int format,int w,int h){}
 public void surfaceDestroyed(SurfaceHolder holder){release();}
 private void release(){alive=false;if(camera!=null){camera.setPreviewCallback(null);camera.stopPreview();camera.release();camera=null;}}
 @Override protected void onDestroy(){release();decode.shutdown();super.onDestroy();}
}
